import { useEffect, useState, useMemo, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Newspaper, Calendar, ExternalLink, X } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { AISummaryDialog } from "@/components/AISummaryDialog";
import { LiveSearchInput } from "@/components/LiveSearchInput";
import { applyHiddenSourceFilter, shouldShowFeedItem, sortByPriorityThenRecency } from "@/lib/feed-filters";
import { useBackgroundRefreshListener } from "@/hooks/useBackgroundRefreshListener";

type ThreatItem = {
  id: string;
  title: string;
  link: string;
  excerpt: string | null;
  severity: string;
  source_name: string;
  category: string;
  published_at: string;
  ai_summary?: string | null;
  ai_summary_model?: string | null;
  ai_summary_generated_at?: string | null;
};

function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

const severityColor: Record<string, string> = {
  critical: "bg-destructive/15 text-destructive border-destructive/40",
  high: "bg-orange-400/15 text-orange-400 border-orange-400/40",
  medium: "bg-blue-400/15 text-blue-400 border-blue-400/40",
  low: "bg-green-500/15 text-green-400 border-green-500/40",
};

export default function News() {
  const { toast } = useToast();
  const [items, setItems] = useState<ThreatItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [sevFilter, setSevFilter] = useState("all");

  const loadNews = useCallback(async (silent = false) => {
    let { data, error } = await applyHiddenSourceFilter(
      supabase
        .from("threat_items")
        .select("id,title,link,excerpt,severity,source_name,category,published_at,fetched_at,ai_summary,ai_summary_model,ai_summary_generated_at")
    )
      .order("fetched_at", { ascending: false, nullsFirst: false })
      .limit(200);
    if (error?.message?.includes("ai_summary") || error?.message?.includes("fetched_at")) {
      const fallback = await applyHiddenSourceFilter(
        supabase.from("threat_items").select("id,title,link,excerpt,severity,source_name,category,published_at,fetched_at")
      )
        .order("fetched_at", { ascending: false, nullsFirst: false })
        .limit(200);
      data = fallback.data as any;
      error = fallback.error as any;
    }
    if (error) {
      if (!silent) toast({ title: "Failed to load", description: error.message, variant: "destructive" });
    } else {
      setItems(sortByPriorityThenRecency(((data || []) as ThreatItem[]).filter(shouldShowFeedItem)));
    }
    if (!silent) setLoading(false);
  }, [toast]);

  useBackgroundRefreshListener(() => { loadNews(true); });

  useEffect(() => {
    loadNews();

    const channel = supabase
      .channel("news_live")
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "threat_items" }, (payload) => {
        const item = payload.new as ThreatItem;
        if (!shouldShowFeedItem(item)) return;
        setItems((prev) => sortByPriorityThenRecency([item, ...prev.filter(i => i.id !== item.id)]).slice(0, 200));
      })
      .on("postgres_changes", { event: "UPDATE", schema: "public", table: "threat_items" }, (payload) => {
        const updated = payload.new as ThreatItem;
        setItems((prev) => {
          const idx = prev.findIndex((i) => i.id === updated.id);
          if (idx === -1) return prev;
          const next = prev.slice();
          next[idx] = { ...next[idx], ...updated };
          return next;
        });
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [toast]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return items.filter(i => {
      if (sevFilter !== "all" && i.severity !== sevFilter) return false;
      if (q && !i.title.toLowerCase().includes(q) && !(i.excerpt || "").toLowerCase().includes(q)) return false;
      return true;
    });
  }, [items, search, sevFilter]);

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-6">
        <div className="flex items-center gap-3 mb-2">
          <Newspaper className="h-6 w-6 text-primary" />
          <h1 className="text-3xl font-bold tracking-tight">Security News</h1>
        </div>
        <p className="text-muted-foreground text-sm">
          Latest cybersecurity news, industry updates, and threat landscape reports.
        </p>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-2 mb-4">
        <LiveSearchInput
          value={search}
          onChange={setSearch}
          placeholder="Search news, keywords…"
          className="flex-1 min-w-56"
        />
        <div className="flex gap-1">
          {["all", "critical", "high", "medium", "low"].map(s => (
            <Button key={s} size="sm" variant={sevFilter === s ? "default" : "outline"} onClick={() => setSevFilter(s)} className="h-8 text-xs capitalize">
              {s}
            </Button>
          ))}
        </div>
        {(search || sevFilter !== "all") && (
          <Button size="sm" variant="ghost" onClick={() => { setSearch(""); setSevFilter("all"); }} className="h-8 text-xs gap-1">
            <X className="h-3.5 w-3.5" /> Clear
          </Button>
        )}
      </div>

      <p className="text-xs text-muted-foreground mb-4">Showing {filtered.length} of {items.length} articles</p>

      {loading ? (
        <div className="text-center py-16 text-muted-foreground">Loading news…</div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">No news items match your filter.</div>
      ) : (
        <div className="flex flex-col gap-3">
          {filtered.map((item) => (
            <Card key={item.id} className="border-border/60 bg-card/60 backdrop-blur hover:border-primary/40 transition-all">
              <CardContent className="p-4">
                <div className="flex flex-col gap-2 md:flex-row md:items-start md:gap-4">
                  <div className="flex gap-2 flex-shrink-0">
                    <Badge className={`border text-[10px] ${severityColor[item.severity] || ""}`}>
                      {item.severity.toUpperCase()}
                    </Badge>
                    <Badge variant="secondary" className="text-[10px]">{item.category}</Badge>
                  </div>
                  <div className="flex-1 min-w-0">
                    <a href={item.link} target="_blank" rel="noopener noreferrer" className="font-medium text-sm hover:text-primary hover:underline leading-snug">
                      {item.title}
                    </a>
                    {item.excerpt && <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{item.excerpt}</p>}
                  </div>
                  <div className="flex items-center gap-3 text-xs text-muted-foreground flex-shrink-0">
                    <span className="flex items-center gap-1"><Calendar className="h-3 w-3" />{timeAgo(item.published_at)}</span>
                    <span className="text-[10px]">{item.source_name}</span>
                    <AISummaryDialog
                      summary={item.ai_summary}
                      generatedAt={item.ai_summary_generated_at}
                      model={item.ai_summary_model}
                      title="AI Summary"
                      triggerLabel="AI"
                      className="h-7 px-2 text-[11px]"
                      itemId={item.id}
                      onGenerated={(s, m, g) => setItems(prev => prev.map(i => i.id === item.id ? { ...i, ai_summary: s, ai_summary_model: m, ai_summary_generated_at: g } : i))}
                    />
                    <a href={item.link} target="_blank" rel="noopener noreferrer" className="text-primary">
                      <ExternalLink className="h-3 w-3" />
                    </a>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}
